const html = String($json.data ?? $json.html_content ?? "");

// vezmi payload z Trigger node
const trigger = $('Trigger').first().json;

const language = String(trigger.language ?? '').trim().toLowerCase();
const originalProject = String(trigger.project ?? '');

// ---------- hreflang / project url ----------
const hreflangMap = {
  czech: 'cs',
  english: 'en',
  polish: 'pl',
  german: 'de',
};

const wantedLang = hreflangMap[language] || 'cs';
const normalizedHtml = html.replace(/\\"/g, '"');

const hreflangMatches = [...normalizedHtml.matchAll(
  /<link[^>]+rel=["']alternate["'][^>]+hreflang=["']([^"']+)["'][^>]+href=["']([^"']+)["'][^>]*\/?>/gi
)];

let project_url = '';
let hreflang_found = false;

for (const match of hreflangMatches) {
  const hreflang = String(match[1] || '').toLowerCase();
  const href = String(match[2] || '');

  if (hreflang === wantedLang) {
    project_url = href;
    hreflang_found = true;
    break;
  }
}

// fallback na původní project URL z Triggeru
if (!project_url) {
  project_url = String($('Trigger').item.json.project ?? '');
}

// ---------- helpers ----------
function stripNoContent(input) {
  return String(input || "")
    .replace(/<script\b[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript\b[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<svg\b[\s\S]*?<\/svg>/gi, " ")
    .replace(/<!--([\s\S]*?)-->/g, " ");
}

function decodeBasic(text) {
  return String(text || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#0*39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");
}

function clean(fragment) {
  return decodeBasic(String(fragment || ""))
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n[ \t]+/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

// univerzální převod celého dokumentu na text
function universalText(htmlDoc) {
  const s = stripNoContent(htmlDoc)
    .replace(/<header\b[\s\S]*?<\/header>/gi, " ")
    .replace(/<nav\b[\s\S]*?<\/nav>/gi, " ")
    .replace(/<footer\b[\s\S]*?<\/footer>/gi, " ")
    .replace(/<aside\b[\s\S]*?<\/aside>/gi, " ");
  const body = (s.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i) || [])[1] || s;
  return clean(body);
}

// ---------- structured extraction ----------
let articlePart = html;

const articleMatch = html.match(
  /<div class="content com realization-detail">([\s\S]*?)<section class="container contact text-center"/i
);
if (articleMatch) articlePart = articleMatch[1];

const parts = [];
const mainTitleMatch = articlePart.match(/<div class="header-text">\s*<h1[^>]*>([\s\S]*?)<\/h1>/i);
if (mainTitleMatch) {
  const t = clean(mainTitleMatch[1]);
  if (t) parts.push(t);
}

const sectionRegex = /<section[^>]*class="([^"]*)"[^>]*>([\s\S]*?)<\/section>/gi;
let secMatch;
while ((secMatch = sectionRegex.exec(articlePart)) !== null) {
  const className = secMatch[1] || "";
  const sectionHtml = secMatch[2];

  if (/header-section/.test(className)) continue;
  if (/wide-swiper-section/.test(className)) continue;

  const headingMatch = sectionHtml.match(/<(h2|h3)[^>]*>([\s\S]*?)<\/\1>/i);
  if (headingMatch) {
    const title = clean(headingMatch[2]);
    if (title) parts.push(title);
  }

  const pRegex = /<p[^>]*>([\s\S]*?)<\/p>/gi;
  let pMatch;
  while ((pMatch = pRegex.exec(sectionHtml)) !== null) {
    const paragraph = clean(pMatch[1]);
    if (paragraph) parts.push(paragraph);
  }
}

// výsledek ze strukturované části
let page_text = parts.join("\n\n").trim();

// ---------- fallback ----------
const usedFallback = !page_text || page_text.length < 300;
if (usedFallback) {
  page_text = universalText(html);
}

return {
  ...$json,
  project_url,
  page_text,
  _debug: {
    language,
    wantedLang,
    hreflang_found,
    inputLen: html.length,
    outputLen: page_text.length,
    usedFallback,
  },
};

